'use strict';

/**
 * Binary-heap priority queue with a pluggable comparator.
 * The comparator receives two elements (a, b) and must return a number:
 *   < 0  -> a has higher priority (comes out first)
 *   > 0  -> b has higher priority
 *   = 0  -> tie (order unspecified)
 */
class PriorityQueue {
  constructor(comparator = (a, b) => a - b) {
    if (typeof comparator !== 'function') {
      throw new TypeError('comparator must be a function (a, b) => number');
    }
    this._cmp = comparator;
    this._heap = [];
  }

  get size() {
    return this._heap.length;
  }

  /** Look at the highest-priority element without removing it. */
  peek() {
    return this._heap.length > 0 ? this._heap[0] : undefined;
  }

  /** Insert an element. */
  push(value) {
    const heap = this._heap;
    heap.push(value);
    this._siftUp(heap.length - 1);
    return this;
  }

  /** Remove and return the highest-priority element. Throws if empty. */
  pop() {
    if (this._heap.length === 0) {
      throw new Error('PriorityQueue is empty');
    }
    const heap = this._heap;
    const top = heap[0];
    const last = heap.pop();
    if (heap.length > 0) {
      heap[0] = last;
      this._siftDown(0);
    }
    return top;
  }

  _siftUp(i) {
    const heap = this._heap;
    const value = heap[i];
    while (i > 0) {
      const parent = (i - 1) >> 1;
      if (this._cmp(value, heap[parent]) < 0) {
        heap[i] = heap[parent];
        i = parent;
      } else {
        break;
      }
    }
    heap[i] = value;
  }

  _siftDown(i) {
    const heap = this._heap;
    const n = heap.length;
    const value = heap[i];
    for (;;) {
      const left = 2 * i + 1;
      if (left >= n) break;
      const right = left + 1;
      let best = left;
      if (right < n && this._cmp(heap[right], heap[left]) < 0) best = right;
      if (this._cmp(heap[best], value) < 0) {
        heap[i] = heap[best];
        i = best;
      } else {
        break;
      }
    }
    heap[i] = value;
  }
}

/**
 * Merge k sorted arrays into a single sorted array using a PriorityQueue.
 * Each array may be empty; the inputs are not mutated.
 */
function mergeSorted(arrays) {
  const result = [];
  // Tie-break by source index so the sort stays stable across equal values.
  const pq = new PriorityQueue((a, b) =>
    a.value !== b.value ? a.value - b.value : a.source - b.source
  );
  for (let s = 0; s < arrays.length; s++) {
    if (arrays[s].length > 0) {
      pq.push({ value: arrays[s][0], source: s, index: 0 });
    }
  }
  while (pq.size > 0) {
    const { value, source, index } = pq.pop();
    result.push(value);
    const arr = arrays[source];
    const next = index + 1;
    if (next < arr.length) {
      pq.push({ value: arr[next], source, index: next });
    }
  }
  return result;
}

module.exports = { PriorityQueue, mergeSorted };

