'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');

const { PriorityQueue, mergeSorted } = require('./pq.js');

// Seeded PRNG (mulberry32) for reproducible random inputs.
function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

test('min-heap comparator: smallest pops first', () => {
  const pq = new PriorityQueue((a, b) => a - b);
  [5, 1, 3, 2, 4].forEach((n) => pq.push(n));
  assert.equal(pq.size, 5);
  assert.equal(pq.peek(), 1);
  assert.deepEqual(
    Array.from({ length: 5 }, () => pq.pop()),
    [1, 2, 3, 4, 5]
  );
  assert.equal(pq.size, 0);
});

test('max-heap comparator: largest pops first', () => {
  const pq = new PriorityQueue((a, b) => b - a);
  [5, 1, 3, 2, 4].forEach((n) => pq.push(n));
  assert.equal(pq.peek(), 5);
  assert.deepEqual(
    Array.from({ length: 5 }, () => pq.pop()),
    [5, 4, 3, 2, 1]
  );
});

test('comparator on objects by deadline field', () => {
  const tasks = [
    { name: 'c', deadline: 30 },
    { name: 'a', deadline: 10 },
    { name: 'd', deadline: 40 },
    { name: 'b', deadline: 20 },
  ];
  const pq = new PriorityQueue((x, y) => x.deadline - y.deadline);
  tasks.forEach((t) => pq.push(t));
  assert.equal(pq.peek().name, 'a');
  assert.deepEqual(
    Array.from({ length: 4 }, () => pq.pop().name),
    ['a', 'b', 'c', 'd']
  );
});

test('pop order on 1000 seeded random numbers equals sort', () => {
  const rand = mulberry32(1234567);
  const input = Array.from({ length: 1000 }, () => Math.floor(rand() * 100000));
  const pq = new PriorityQueue((a, b) => a - b);
  input.forEach((n) => pq.push(n));
  assert.equal(pq.size, 1000);

  const popped = [];
  while (pq.size > 0) popped.push(pq.pop());
  assert.deepEqual(popped, [...input].sort((a, b) => a - b));
  assert.equal(popped.length, 1000);
});

test('mergeSorted equals flat().sort() on seeded random inputs incl. empties', () => {
  const rand = mulberry32(987654321);

  // Deterministic small case including empty arrays.
  assert.deepEqual(mergeSorted([[], [1], [], [0, 2], []]), [0, 1, 2]);
  assert.deepEqual(mergeSorted([]), []);
  assert.deepEqual(mergeSorted([[], []]), []);

  for (let round = 0; round < 25; round++) {
    const k = 1 + Math.floor(rand() * 8); // up to 8 arrays
    const arrays = Array.from({ length: k }, () => {
      // Some rounds produce empty arrays naturally.
      const n = rand() < 0.25 ? 0 : Math.floor(rand() * 50);
      const arr = Array.from({ length: n }, () => Math.floor(rand() * 1000));
      return arr.sort((a, b) => a - b);
    });
    const expected = arrays.flat().sort((a, b) => a - b);
    assert.deepEqual(mergeSorted(arrays), expected);
  }
});

test('peek on empty returns undefined while pop on empty throws', () => {
  const pq = new PriorityQueue((a, b) => a - b);
  assert.equal(pq.peek(), undefined);
  assert.equal(pq.size, 0);
  assert.throws(() => pq.pop(), /empty/i);
});

